static inline fixed_type_general call_atan_unit_lut(fixed_type_general z) {
#pragma HLS INLINE
#pragma HLS BIND_STORAGE variable=atan_unit_lut type=ROM_2P impl=LUTRAM

    fixed_type_general zz = z;
    if (zz < FX_ZERO) zz = -zz;
    if (zz > FX_ONE)  zz = FX_ONE;

    int idx = (int)(zz * ATAN_UNIT_LUT_STEP_INV + FX_HALF);
    if (idx < 0) idx = 0;
    if (idx >= ATAN_UNIT_LUT_SIZE) idx = ATAN_UNIT_LUT_SIZE - 1;

    return atan_unit_lut[idx];
}
